'use strict';
// Presentation only: never write to the original itinerary objects.
const journeyToday=()=>tripToday(new Date(),DATA.days,tripCalendarChanges).day;
const journeyTitle=(d,r)=>d.id===3&&r.stepTitle==='桑拿备选'?'酒店泡浴':r.stepTitle||'行程安排';
const journeyStages=[['1','出发 · 赫尔辛基'],['2,3,4,5','特罗姆瑟'],['6,7,8','罗弗敦'],['9','博德 → 奥斯陆'],['10','抵达冰岛'],['11','南岸 → 维克'],['12,13','冰河湖 · Hali'],['14','黄金圈'],['15','Silfra → 雷克雅未克'],['16','哥本哈根'],['17','返程 · 赫尔辛基'],['18','北京']];
function journeyDate(value=state.day,mapMode=false){return `<label class="journey-date"><span>选择日期</span><select data-journey-date="${mapMode?'map':'day'}" aria-label="${mapMode?'地图日期':'行程日期'}">${DATA.days.map(d=>`<option value="${d.id}" ${d.id===+value?'selected':''}>${shortDate(d.date)} · ${d.title}</option>`).join('')}</select></label>`;}
function journeyPosition(d,now=new Date(),rows=selectedPlan(d)){
 const pos=planPosition(d,now,rows),time=+now;
 const past=rows.map((r,i)=>{const w=stepWindow(d,r);if(!w)return false;if(w.end!==null)return time>=w.end;const next=rows.slice(i+1).map(x=>stepWindow(d,x)).find(x=>x&&x.start>w.start);return !!next&&time>=next.start;});
 if(!pos.live)return {...pos,past:rows.map(()=>false),primary:0,following:rows.length>1?1:-1};
 let primary=pos.current>=0?pos.current:pos.approximate>=0?pos.approximate:pos.next;
 // Keep unclocked actions between the last elapsed window and next timed action.
 const lastEnded=rows.reduce((a,r,i)=>past[i]?i:a,-1);
 if(primary>lastEnded+1&&lastEnded>=0)primary=lastEnded+1;
 if(primary<0&&lastEnded<rows.length-1)primary=lastEnded+1;
 return {...pos,past,primary,following:primary>=0&&primary+1<rows.length?primary+1:-1};
}
function journeyAction(d,index,label,homeMode=false){const rows=selectedPlan(d),r=rows[index];return `<article class="journey-action"><p class="editor-label">${label}${homeMode?' · '+shortDate(d.date):''}</p>${r?`<h2>${esc(journeyTitle(d,r))}</h2><p class="journey-action-time">${esc(r.time)}</p><button ${homeMode?'data-day="'+d.id+'" data-focus-step="'+index+'"':'data-step-focus="'+index+'"'}>查看安排 →</button>`:`<h2>当天安排已到尾声</h2><button data-day="${Math.min(18,d.id+1)}">${d.id<18?'查看明天 →':'查看返程安排 →'}</button>`}</article>`;}
timeCard=function(d,now=new Date()){const p=journeyPosition(d,now);return `<div class="journey-actions">${journeyAction(d,p.primary,p.live?(p.current>=0?'当前计划':p.approximate>=0?'当前安排 · 约定时段':'接下来'):'当天第一段')}${journeyAction(d,p.following,'随后')}</div>`;};
routeOverview=function(){return `<section class="home-route"><div><p class="editor-label">18天 · 全程路线</p><p class="route-sentence">北京 → 赫尔辛基 → 特罗姆瑟 → 罗弗敦 → 博德 → 奥斯陆 → 冰岛 → 哥本哈根 → 赫尔辛基 → 北京</p><p class="experience-line">观鲸 · 峡湾海岸 · 温泉 · 冰河湖 · 蓝冰洞 · Silfra浮潜</p><button class="action-button" data-mapday="all">查看全程路线 ↗</button></div><button class="home-atlas" data-mapday="all" aria-label="打开全程路线">${atlas()}</button></section>`;};
home=function(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges),d=DATA.days[t.day-1],before=t.boundary==='first',f=DATA.days[0].flights[0],days=Math.max(0,Math.ceil((tripLocalTimestamp(DATA.days[0].date,'00:00','Asia/Shanghai')-Date.now())/86400000)),p=journeyPosition(d);return `<section class="journal-hero journey-hero"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="hero-copy"><p>2026.10.18 — 11.04 · 挪威与冰岛</p><h1>Nordic Journal <em>2026</em></h1>${journeyDate(t.day)}</div></section><section class="journey-home-status"><header><span>${before?'距出发 '+days+' 天':t.inTrip?shortDate(d.date)+' · '+esc(d.title):'旅程回顾'}</span><button data-view="itinerary">全部日期 →</button></header>${before?`<div class="journey-actions"><article class="journey-action"><p class="editor-label">出发 · 10月18日</p><h2>${esc(f[0])} · ${esc(f[1])} → ${esc(f[4])}</h2><p class="journey-action-time">北京 ${esc(f[3])} → 赫尔辛基 ${esc(f[6])}</p><button data-day="1">出发安排 →</button></article><article class="journey-action"><p class="editor-label">抵达后</p><h2>入境取箱 · 酒店入住</h2><p class="journey-action-time">存好行李，再选择休息或夜游</p><button data-day="1">抵达安排 →</button></article></div>`:t.inTrip?`<div class="journey-actions">${journeyAction(d,p.primary,p.current>=0?'当前计划':'接下来',true)}${p.following>=0?journeyAction(d,p.following,'随后',true):d.id<18?journeyAction(DATA.days[d.id],0,'明天',true):journeyAction(d,-1,'返程',true)}</div>`:`<button class="action-button" data-view="itinerary">回顾十八天 →</button>`}</section>${routeOverview()}<footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源</button><button data-offline>离线资料</button><button data-top>回到顶部 ↑</button></div></footer>`;};
const countryCompactDays=compactDays;
compactDays=function(filter=browseSearch,region=browseCountry){if(region==='all'||['挪威','冰岛','transfer'].includes(region))return countryCompactDays(filter,region);const allowed=region.split(',').map(Number),html=countryCompactDays(filter,'all'),template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.compact-day').forEach(el=>{if(!allowed.includes(+el.querySelector('[data-day]').dataset.day))el.remove();});template.content.querySelectorAll('.phase-title').forEach(el=>{if(!el.nextElementSibling?.classList.contains('compact-day'))el.remove();});return template.innerHTML||'<p class="empty-state">没有匹配的安排。</p>';};
itineraryView=function(){return `<header class="utility-header"><p class="editor-label">18 OCT — 04 NOV 2026</p><h1>全程日程</h1><label class="journey-date"><span>旅程阶段</span><select data-journey-stage aria-label="按实际旅程顺序筛选"><option value="all">完整旅程</option>${journeyStages.map(([k,n])=>`<option value="${k}" ${browseCountry===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="destination-search">${ico('pin')}<input id="destinationSearch" type="search" value="${esc(browseSearch)}" placeholder="目的地、日期或航班" aria-label="搜索行程"></label><p class="search-count" id="searchCount" role="status">按旅程先后排列</p></header><div id="compactIndex">${compactDays()}</div>`;};
function journeyParking(key){const p=TRAVEL_SUPPORT.placeParking(key);return p?`<button data-parking="${esc(key)}">停车与缴费</button>`:'';}
function travellerNotes(d){let text=d.notes||'';text=text.replace(/酒店入住开始时间待核对/g,'入住时间请向酒店确认').replace(/Å镇精确日照待补，不能套成分钟级当地结果。/g,'这里的日照时间以莱克内斯区域为参考。').replace(/当天具体日出日落待补核，/g,'').replace(/先列待订备选，未预订/g,'安排泡浴，需提前预约').replace(/Arctic Wellness待订备选/g,'Arctic Wellness酒店泡浴，需提前预约').replace(/待路线最终确认后细化/g,'实际以当日道路及导航为准').replace(/后续确认性总结直接推进，只有实质取舍才提问。/g,'').replace(/用户已确定的内容：|用户已确认：|餐饮已确认：/g,'').replace(/用户已确认加入Nusfjord。/g,'当天保留Nusfjord游览。').replace(/具体交通仍待确认/g,'出发前查看公交停站，返程可叫出租车').replace(/尚待核实|尚未核实|尚未核验|待核实|待核对|待补核|待补充|待订/g,'请提前确认').replace(/未核实/g,'请出发前确认');
 // Repeated itinerary tables are already represented by the interactive timeline.
 text=text.replace(/(?:^|\n)\|[^\n]*(?:时间|当地时间)[^\n]*\|[\s\S]*?(?=\n\n|$)/g,'');
 text=text.replace(/^### (建议时间线|固定信息与共同上午)\s*$/gm,'');return text;}
function journeyStepNotes(d,rows){const result=rows.map(()=>[]),left=[];for(const block of travellerNotes(d).split(/\n\n+/)){if(!block.trim())continue;let index=-1;const themes=[[/Arctic Wellness|共享场90分钟/,/桑拿备选/],[/Nappstraumtunnelen|Flesa|引导通行/,/隧道排队|前往隧道/],[/Tromsøbrua|大桥施工/,/教堂外观/],[/Blue当前|Comfort：|Blue票|Blue营业|四个20–28寸/,/Blue温泉/],[/Saman|Skjól|七步|Sky票/,/Sky温泉/],[/Full Steam|特色餐厅|餐厅菜单/,/晚餐/],[/四晚|保温袋|食材/,/四晚采购/]];for(const [content,title] of themes){if(content.test(block)){index=rows.findIndex(r=>title.test(r.stepTitle||''));if(index>=0)break;}}if(index>=0)result[index].push(block);else left.push(block);}return {rows:result.map(x=>x.join('\n\n')),tail:left.join('\n\n')};}
function journeyPlace(k){const p=DATA.places[k],src=smallPhoto(k);if(!p)return '';return `<details class="journey-disclosure place-inline"><summary>${esc(p.name)} · 简介${src?'与照片':''}</summary><div class="journey-detail-body">${src?`<button class="journey-place-image" data-photo="${k}" aria-label="全屏查看${esc(p.name)}"><img src="${src}" width="720" height="480" alt="${esc(p.name)}" loading="lazy" decoding="async"></button>`:''}<p>${inline(travellerNotes({notes:p.desc||''}))}</p>${p.hours?`<p class="place-hours">${inline(travellerNotes({notes:p.hours}))}</p>`:''}${p.source?ext(p.source,'地点官网与游览说明','small-link'):''}${p.stay?`<p class="info-caption">停留 ${esc(p.stay)}</p>`:''}${p.tips?.length?`<ul>${p.tips.map(x=>'<li>'+inline(travellerNotes({notes:x}))+'</li>').join('')}</ul>`:''}</div></details>`;}
function journeyAssociations(d,rows){const sets=rows.map(()=>[]),keys=[...new Set([...selectedSpots(d),...(d.venues||[])])];for(const key of keys){const p=DATA.places[key];if(!p)continue;const terms=[p.name,p.en,key.length>4?key:''].filter(Boolean);let best=-1,score=0;rows.forEach((r,i)=>{let n=(r.nav||[]).includes(key)?20:0;if(terms.some(x=>r.text.includes(x)||r.stepTitle?.includes(x)))n+=8;if(/漫步|拍照|午餐|购物|观景|海岸|沙滩|瀑布|泡浴|缆车|间歇泉/.test(r.stepTitle))n+=5;if(/前往|通行|排队|自驾|返回|寄存|放行/.test(r.stepTitle))n-=12;if(n>score){best=i;score=n;}});if(best<0||score<8){const fallback={3:'逛街',5:'超市补给',7:'山湖漫步',9:'市区购物',11:'四晚采购',13:'返回Hali',15:'纪念品购物',16:'市区购物'}[d.id];best=rows.findIndex(r=>r.stepTitle===fallback);}if(best>=0)sets[best].push(key);}return sets;}
renderTimeline=function(d){const rows=selectedPlan(d),pos=journeyPosition(d),stay=stayRow(d,rows),pictures=journeyAssociations(d,rows),stepNotes=journeyStepNotes(d,rows),branch=d.variants?.[state.variants[d.id]||'A']?.timeline||[],firstBranch=rows.findIndex(r=>branch.includes(r)),decision=rows.findIndex(r=>r.stepTitle==='路线选择');const rowHTML=(r,i)=>{const s=TRAVEL_SUPPORT.row(d,r);if(d.id===3&&r.stepTitle==='桑拿备选')s.reminder='提前至少2小时向酒店预约20:00泡浴；需16岁以上，90分钟400 NOK/人。留意下山与晚餐衔接。';const b=DATA.bookings.find(b=>b.day===d.id&&bookingRow(d,b,rows)===i),critical=s.critical.length||r.critical;return `<article id="step-${i}" data-row-index="${i}" class="timeline-row ${critical?'time-critical':''} ${pos.primary===i&&pos.live?'is-current':''}"><div class="timeline-time">${inline(r.time)}${timelineClockLabel(d,r)?`<small>${esc(timelineClockLabel(d,r))}</small>`:''}</div><div class="timeline-text"><div class="timeline-heading"><h3 class="step-title">${esc(journeyTitle(d,r))}</h3><span class="step-state">${pos.live&&pos.primary===i?'当前计划':pos.live&&pos.following===i?'随后':''}</span></div>${s.durations.filter(x=>x.kind!=='计划时段').length?`<p class="step-duration">${s.durations.filter(x=>x.kind!=='计划时段').map(x=>esc(x.kind)+' '+esc(x.label)).join(' · ')}</p>`:''}${s.critical.map(c=>`<p class="journey-critical"><span aria-hidden="true">!</span><strong>${esc(c.time)}</strong> ${esc(c.action)}<small>${esc(c.basis.replace('原资料：','').replace('原计划','计划'))}</small></p>`).join('')}<p class="step-description">${inline(travellerNotes({notes:d.id===3&&r.stepTitle==='桑拿备选'?r.text.replace(/备选/g,'').replace(/待订/g,'请提前预约'):r.text}))}</p>${s.reminder?`<p class="step-reminder">${esc(s.reminder)}</p>`:r.critical?`<p class="step-reminder">${esc(r.critical)}</p>`:''}${d.variants&&i===decision?routeChoice(d):''}${b?`<details class="journey-disclosure"><summary>活动票与集合说明</summary><div class="journey-detail-body">${bookingInline(b)}</div></details>`:''}${i===stay?`<details class="journey-disclosure" id="todayStay"><summary>今晚住宿 · ${esc(DATA.hotels[d.hotel]?.cn)}</summary><div class="journey-detail-body">${hotelQuick(d)}</div></details>`:''}<div class="step-locations">${(r.nav||[]).filter(k=>!k.startsWith('hotel:')).map(k=>`<button data-step-map="${i}" data-map-key="${k}">${esc(DATA.places[k]?.name||k)} · 地图</button>`).join('')}${(r.nav||[]).length?`<button data-navigation="${r.nav[0]}">导航 ↗</button>`:''}${s.parking.map(p=>journeyParking(p.placeKey)).join('')}</div>${pictures[i].map(journeyPlace).join('')}${stepNotes.rows[i]?`<details class="journey-disclosure"><summary>这一段的实用说明</summary><div class="journey-detail-body rich">${markdown(stepNotes.rows[i])}</div></details>`:''}${d.id===13&&r.stepTitle==='蓝冰洞'?'<details class="journey-disclosure"><summary>留守同伴 · Hali附近</summary><div class="journey-detail-body"><p>优先酒店旁Þórbergssetur书墙与文化馆；外观10–15分钟，开放时入内45–60分钟。咖啡馆常规11:00–15:00，入内时段向前台了解。只走酒店周边平坦短路，风雨大时留室内；不步行前往冰河湖。</p></div></details>':''}${d.id===15&&r.stepTitle==='峡谷浮潜'?'<details class="journey-disclosure"><summary>留守同伴 · 集合点附近</summary><div class="journey-detail-body"><p>在P5与集合点附近等候，可沿安全步道看教堂和农舍外观，往返约30–45分钟。保留车钥匙和保暖衣物；地面结冰、强风时回车内，不独自远走峡谷或沿车道步行。</p></div></details>':''}</div></article>`;};let html='',i=0;while(i<rows.length){if(pos.past[i]&&pos.live){const start=i;while(i<rows.length&&pos.past[i])i++;html+=`<details class="journey-disclosure past-steps"><summary>此前安排 · ${i-start}项 <span>展开查看</span></summary><div class="journey-detail-body">${rows.slice(start,i).map((r,j)=>rowHTML(r,start+j)).join('')}</div></details>`;}else{if(d.variants&&decision<0&&i===firstBranch)html+=`<section class="timeline-decision"><p class="decision-heading">接下来 · 选择安排</p>${routeChoice(d)}</section>`;html+=rowHTML(rows[i],i);i++;}}return `<div class="timeline">${html}</div>`;};
extraDay=function(d){return `<div class="day-closing-notes"><p class="info-caption">日出约 ${esc(d.sun[0])} · 日落约 ${esc(d.sun[1])}</p>${d.alternatives?.filter(a=>!(d.id===3&&a.name?.includes('Arctic Wellness'))).length?`<details class="journey-disclosure"><summary>备选安排</summary><div class="journey-detail-body">${d.alternatives.filter(a=>!(d.id===3&&a.name?.includes('Arctic Wellness'))).map(a=>typeof a==='string'?'<p>'+inline(a)+'</p>':'<p>'+esc(a.name||a.title||'')+' '+esc(a.text||a.desc||'')+'</p>').join('')}</div></details>`:''}<details class="journey-disclosure"><summary>当天餐饮与其他提醒</summary><div class="journey-detail-body"><p>${inline(d.meal||'')}</p><p>${inline(d.drive||'')}</p>${d.alert?'<p>'+inline(d.alert)+'</p>':''}${markdown(journeyStepNotes(d,selectedPlan(d)).tail)}</div></details></div>`;};
dayView=function(){const d=DATA.days[state.day-1],t=tripToday(new Date(),DATA.days,tripCalendarChanges),zone=t.inTrip&&t.day===d.id?t.zone:d.tz;return `<header class="utility-header day-utility"><p class="editor-label">${dateText(d.date)} · ${esc(d.region)} · 第${d.id}天</p><h1>${esc(d.title)}</h1><div class="day-top-controls">${journeyDate(d.id)}<button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 →</button></div><div class="day-clock"><span>${esc(zoneLabel(zone))} <time data-clock-zone="${zone}"></time></span><span>北京时间 <time data-clock-zone="Asia/Shanghai"></time></span></div><div class="utility-actions"><button data-mapday="${d.id}">当天地图 ↗</button><button data-view="itinerary">完整日程</button>${d.hotel?'<button data-scroll-id="todayStay">今晚住宿 ↓</button>':''}</div></header><div id="planNow">${timeCard(d)}</div>${WEATHER_SERVICE.renderShell(d,selectedPlan(d))}<section class="section day-timeline"><div class="section-top"><h2>当天时间线</h2></div><div id="planTimeline">${renderTimeline(d)}</div></section><div id="dayExtras" data-spots="${esc(selectedSpots(d).join('|'))}">${extraDay(d)}</div>${dayPagination(d)}`;};
toolNames.lists='厨房采购';
function journeyToolGroups(entries){const t=journeyToday(),now=Date.now(),elapsed=x=>Number.isFinite(x.endAt)?x.endAt<now:x.end<t,started=x=>Number.isFinite(x.startAt)?x.startAt<=now:x.start<=t,past=entries.filter(elapsed),upcoming=entries.filter(x=>!elapsed(x)),present=upcoming.filter(started),next=upcoming.filter(x=>!started(x));return `${present.length?'<h3 class="tool-period">当前要用</h3>'+present.map(x=>x.html).join(''):''}${next.length?'<h3 class="tool-period">接下来的安排</h3>'+next.map(x=>x.html).join(''):''}${past.length?`<details class="journey-disclosure past-tools"><summary>此前安排 · ${past.length}项</summary><div class="journey-detail-body">${past.map(x=>x.html).join('')}</div></details>`:''}`||'<p class="empty-state">这一天没有相应安排。</p>';}
function journeyBookingWindow(b){const d=DATA.days[b.day-1],title={4:'追鲸',12:'冰湖快艇',13:'蓝冰洞',15:'峡谷浮潜'}[b.day],r=selectedPlan(d).find(r=>r.stepTitle===title);return r?stepWindow(d,r):stepWindow(d,{time:b.time,text:''});}
const previousToolBody=toolBody;
toolBody=function(k){const days=toolDay==='all'?DATA.days:DATA.days.filter(d=>d.id===+toolDay);if(k==='activities')return journeyToolGroups(DATA.bookings.filter(b=>days.some(d=>d.id===b.day)).map(b=>({start:b.day,end:b.day,startAt:journeyBookingWindow(b)?.start,endAt:journeyBookingWindow(b)?.end,html:bookingQuick(b)})));if(k==='flights')return journeyToolGroups(days.flatMap(d=>(d.flights||[]).map(f=>{const r=selectedPlan(d).find(r=>r.text.includes(f[0])&&stepTimeZones(d,r).flight),w=r?stepWindow(d,r):null;return {start:d.id,end:d.id,startAt:w?.start,endAt:w?.end,html:`<article class="tool-flight"><h3>${dateText(d.date)}</h3><div class="flights">${flight(f)}</div><button class="small-link" data-day="${d.id}">当天交通安排 →</button></article>`};})));if(k==='hotels')return journeyToolGroups([...new Set(days.map(d=>d.hotel).filter(Boolean))].map(key=>{const h=DATA.hotels[key],stay=DATA.days.filter(d=>d.hotel===key),first=stay[0],last=stay.at(-1),checkin=selectedPlan(first).find(r=>/入住/.test(r.stepTitle||'')),checkoutDay=DATA.days[last.id],checkout=checkoutDay?.timeline.find(r=>/退房/.test(r.stepTitle||'')),out=checkout&&stepWindow(checkoutDay,checkout);return {start:first.id,end:last.id,startAt:checkin?stepWindow(first,checkin)?.start:null,endAt:out?.end??out?.start??null,html:`<article class="tool-hotel"><p class="editor-label">${shortDate(stay[0].date)}${stay.length>1?' — '+shortDate(stay.at(-1).date):''} · 住宿</p>${hotelButton(key)}<p>${esc(h.address)}</p>${ext(hotelLink(key),'酒店导航','primary-link')}<button data-copy="${esc(h.name+'\n'+h.address)}">复制地址</button></article>`};}));if(k==='lists')return journeyToolGroups(TRAVEL_SUPPORT.purchases.map(p=>({start:p.day,end:p.day,html:`<article class="purchase-suggestion"><p class="editor-label">${shortDate(p.date)} · ${esc(p.time)}</p><h3>${esc(p.title)}</h3><div class="purchase-coverage">${p.coverage.map(c=>`<p><strong>${shortDate(c.date)}</strong> ${[['breakfast','早餐'],['lunch','午餐'],['dinner','晚餐']].filter(([k])=>c[k]).map(([k,n])=>n+'：'+esc(c[k])).join(' · ')}</p>`).join('')}</div><details class="journey-disclosure"><summary>食材搭配建议</summary><div class="journey-detail-body"><p>按人数、食量与喜好调整，可换成顺手买到的食材。</p><ul>${p.suggestions.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p>${esc(p.reminder)}</p></div></details></article>`})));return previousToolBody(k);};
